import{_ as o,H as a,f as i,i as r}from"./chunks/framework.DLd0CbzH.js";const h=JSON.parse('{"title":"ADR-002: Отслеживание победителя и мониторинг статуса закупки","description":"","frontmatter":{"type":"adr","status":"proposed","tags":["agelto","adr","eis","monitoring","winner","lifecycle"],"created":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/ADR/ADR-002_Winner_Tracking_And_Monitoring.md","filePath":"03_Dev/ADR/ADR-002_Winner_Tracking_And_Monitoring.md"}'),t={name:"03_Dev/ADR/ADR-002_Winner_Tracking_And_Monitoring.md"};function d(l,e,c,n,s,_){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-002-отслеживание-победителя-и-мониторинг-статуса-закупки" tabindex="-1">ADR-002: Отслеживание победителя и мониторинг статуса закупки <a class="header-anchor" href="#adr-002-отслеживание-победителя-и-мониторинг-статуса-закупки" aria-label="Permalink to &quot;ADR-002: Отслеживание победителя и мониторинг статуса закупки&quot;">​</a></h1><h2 id="статус" tabindex="-1">Статус <a class="header-anchor" href="#статус" aria-label="Permalink to &quot;Статус&quot;">​</a></h2><p>🟡 Предложено (требует бизнес-валидации) — НЕ принято к реализации.</p><h2 id="контекст" tabindex="-1">Контекст <a class="header-anchor" href="#контекст" aria-label="Permalink to &quot;Контекст&quot;">​</a></h2><p>Анализы ЕИС (см. [[Procurement_Lifecycle]]) поднимают продуктовый тезис: <strong>материалы по смете закупает победитель подряда, а не заказчик</strong>. Текущий пайплайн Agelto заканчивается на парсинге документов закупки и выдаёт лид на этапе извещения — <strong>до того, как победитель известен</strong>. Значит лид может быть преждевременным: целевой контакт для продажи материалов появляется позже, в протоколе подведения итогов.</p><p>Что отсутствует в коде (подтверждено аудитом 2026-06-14, [[Procurement_Lifecycle]] §11):</p><ul><li>статус самой закупки в ЕИС после краулинга не отслеживается (<code>CrawlingStatus</code>/<code>AnalysisStatus</code> описывают обработку документов, не закупку);</li><li>нет полей победителя/контракта на <code>ord_orders</code>, нет <code>OrderMonitoringStatus</code>, нет истории победителей;</li><li>нет джоба-планировщика опроса и парсера протокола итогов;</li><li>сценарии «возврата к жизни» (уклонение, ФАС, расторжение, повтор) не покрыты.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">Это решение меняет трактовку «лида» и расширяет scope за пределы v1 ([[BRD (Agelto)]] — «выдача лида в CRM»). Поэтому фиксируется как **предложение**, не как принятое решение.</p><p></p></div><h2 id="рассмотренные-варианты" tabindex="-1">Рассмотренные варианты <a class="header-anchor" href="#рассмотренные-варианты" aria-label="Permalink to &quot;Рассмотренные варианты&quot;">​</a></h2><h3 id="вариант-a-не-отслеживать-статус-кво" tabindex="-1">Вариант A: не отслеживать (статус-кво) <a class="header-anchor" href="#вариант-a-не-отслеживать-статус-кво" aria-label="Permalink to &quot;Вариант A: не отслеживать (статус-кво)&quot;">​</a></h3><p>Лид выдаётся на этапе извещения; победитель не фиксируется.</p><ul><li>✅ Ноль работы; не зависим от непроверенных деталей ЕИС.</li><li>❌ Лид может быть преждевременным/нерелевантным; теряется самый ценный контакт — победитель.</li></ul><h3 id="вариант-b-html-мониторинг-карточки-закупки" tabindex="-1">Вариант B: HTML-мониторинг карточки закупки <a class="header-anchor" href="#вариант-b-html-мониторинг-карточки-закупки" aria-label="Permalink to &quot;Вариант B: HTML-мониторинг карточки закупки&quot;">​</a></h3><p>Периодически перечитывать <code>common-info.html</code> / <code>documents.html</code>, парсить протокол итогов из HTML.</p><ul><li>✅ Переиспользует уже работающий headless-парсинг и прокси-пул; без токенов/ЭЦП.</li><li>⚠️ Хрупко к смене вёрстки ЕИС (риск R-2); нагрузка/антибот при тысячах закупок; XML-структура протокола не проверена.</li></ul><h3 id="вариант-c-soap-api-еис" tabindex="-1">Вариант C: SOAP API ЕИС <a class="header-anchor" href="#вариант-c-soap-api-еис" aria-label="Permalink to &quot;Вариант C: SOAP API ЕИС&quot;">​</a></h3><p>Запрашивать документы по <code>reestrNumber</code> через SOAP.</p><ul><li>✅ Структурированные данные, надёжнее HTML.</li><li>❌ Требует токена (физлицо — Госуслуги) или ЭЦП (организация) + ГОСТ-шифрование; домены/доступ — внешне-непроверены ([[Procurement_Lifecycle]] §10).</li></ul><h3 id="вариант-d-гибрид-html-листинг-soap-детали" tabindex="-1">Вариант D: гибрид (HTML-листинг + SOAP-детали) <a class="header-anchor" href="#вариант-d-гибрид-html-листинг-soap-детали" aria-label="Permalink to &quot;Вариант D: гибрид (HTML-листинг + SOAP-детали)&quot;">​</a></h3><p>HTML для обнаружения новых закупок, SOAP по <code>reg_number</code> для протоколов/победителя.</p><ul><li>✅ Сильные стороны обоих; SOAP не имеет удобного «листинга новых».</li><li>❌ Двойная интеграция; зависит от доступности SOAP.</li></ul><h2 id="решение-proposed" tabindex="-1">Решение (Proposed) <a class="header-anchor" href="#решение-proposed" aria-label="Permalink to &quot;Решение (Proposed)&quot;">​</a></h2><p>Зафиксировать <strong>предлагаемую форму</strong> без реализации в этой итерации. Предлагаемые артефакты (к проработке после бизнес-валидации):</p><ul><li><code>OrderMonitoringStatus</code> — state-машина закупки в ЕИС (<code>active</code>, <code>awaiting_winner</code>, <code>winner_found</code>, <code>winner_evaded</code>, <code>contract_signed</code>, <code>executing</code>, <code>completed</code>, <code>suspended</code>, <code>failed</code>, <code>cancelled</code>, <code>terminated</code>).</li><li>Поля победителя/контракта на <code>ord_orders</code> (<code>winner_inn/kpp/name</code>, <code>final_price</code>, <code>protocol_published_at</code>, <code>contract_signed_at</code>, <code>monitoring_status</code>, <code>monitoring_next_at</code>, <code>winner_evaded_at</code>, <code>parent_order_id</code>).</li><li>История победителей <code>ord_order_winners</code> (1:N) — для сценария смены победителя при уклонении.</li><li><code>OrderStatusMonitorJob</code> + расписание опроса по статусу ([[Procurement_Lifecycle]] §9) с rate-limit под антибот ЕИС.</li><li>Парсер протокола итогов (извлечение победителя/цены/даты).</li></ul><p><strong>Развилка HTML-vs-SOAP (B/C/D) остаётся открытой</strong> — решается отдельно после проверки реальной структуры данных ЕИС.</p><div class="important custom-block github-alert"><p class="custom-block-title">Гейт реализации</p><p>Кодовая итерация стартует только после: (1) бизнес-валидации тезиса «лид = победитель»; (2) проверки XML-структуры протокола и доступа к данным ЕИС на живом сервисе; (3) выбора B/C/D. До этого — только документация ([[Procurement_Lifecycle]], этот ADR, риск R-11 в [[Risk_Register (Agelto)]]).</p></div><h2 id="последствия" tabindex="-1">Последствия <a class="header-anchor" href="#последствия" aria-label="Permalink to &quot;Последствия&quot;">​</a></h2><ul><li>✅ Зафиксировано ценное доменное знание и осознанная развилка — без преждевременного кода.</li><li>⚠️ При принятии (Accepted) — расширение модели данных (<code>ord_*</code>), новые Horizon-очереди, нагрузка на краулер/прокси (мониторинг тысяч закупок), зависимость от непроверенных деталей ЕИС.</li><li>⚠️ Потребует подключения Стадии 5 (<code>OrderParsing</code>, сейчас заглушка) и связи <code>ord_orders ↔ plt_crawler_links</code>.</li><li>⚠️ При принятии — правка трактовки «лида» в [[BRD (Agelto)]] и [[Architecture_Agelto]].</li></ul><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>[[Procurement_Lifecycle]] — справочник по жизненному циклу ЕИС, реестр статусов, достоверность источника</li><li>[[Risk_Register (Agelto)]] R-11 — риск «результат закупки не отслеживается»</li><li>[[Architecture_Agelto]] §7 (схема <code>ord_*</code>), §15 (открытые вопросы)</li><li>[[Dev_Status]] — «Мониторинг результата закупки» в «Не начат»</li></ul>',30)])])}const p=o(t,[["render",d]]);export{h as __pageData,p as default};
